  assert.deepEqual(market.backupState(),sourceMarket);assert.deepEqual(feed.backupState(),sourceFeed);const copied=github.backupState();assert.deepEqual(copied.sources,sourceGithub.sources);assert.deepEqual(copied.running,[]);assert.deepEqual(copied.releases.map(row=>row.release).sort((a,b)=>a.digest.localeCompare(b.digest)),sourceGithub.releases.map(row=>row.release).sort((a,b)=>a.digest.localeCompare(b.digest)));
  const localState=local.backupState();assert.deepEqual(localState.sources.map(row=>({...row,root:sourceLocal.sources.find(old=>old.id===row.id).root,identity:sourceLocal.sources.find(old=>old.id===row.id).identity})),sourceLocal.sources);
  assert.equal(localState.sources[1].enabled,false);assert.equal(market.backupState().preferences.enabled,1);assert.equal(feed.snapshot().automatic,true);assert.equal(github.list()[0].pending,f.second.digest);
  for(const provider of[market.provider(),local.provider(),github.provider()])assert.deepEqual(await provider.list({signal:signal()}),[]);
  await github.automaticCheck();await feed.automaticCheck();assert.throws(()=>market.cancelPending(f.initial.manifest.id),/恢复的技能/);assert.throws(()=>local.disable(sourceLocal.sources[0].id),/恢复的技能/);await assert.rejects(github.download(f.git.spec),/恢复的技能/);await assert.rejects(feed.check(),/恢复的技能/);
  assert.deepEqual(f.market.backupState(),sourceMarket);assert.deepEqual(f.local.backupState(),sourceLocal);assert.deepEqual(f.github.backupState(),sourceGithub);assert.deepEqual(f.feed.backupState(),sourceFeed);assert.equal(f.git.calls.length,networkBefore);
  // Only explicitly named, canonical fixture leaf directories are moved.
  for(const path of[f.home,f.agents,f.custom,f.bundled,f.project,f.a,f.b,join(f.root,'github')]){const actual=await realpath(path),part=relative(f.root,actual);assert.ok(part&&!isAbsolute(part)&&!part.startsWith('..')&&!/[\\/]/.test(part));await rename(actual,path+'.EXAMPLE_OFFLINE');}
  const ctx=new Context(),abort=new AbortController(),fs=new FileSystemSkillProvider(ctx,{signal:abort.signal,invalidate(){}},{...result.filesystems[0].config,watch:false});try{const observed=await fs.list({cwd:result.projects[0].root,signal:abort.signal});assert.ok(Array.isArray(observed));assert.equal(observed.length,6,JSON.stringify({mapped:result.filesystems,projects:result.projects,roles:f.restored.roots.map(row=>({kind:row.origin.kind,provenance:row.origin.provenance,path:row.restoredPath})),observed}));assert.deepEqual(observed.map(row=>row.source),['project-dsh','project-agents','custom','user-dsh','user-agents','bundled']);for(const item of observed)assert.ok((await fs.get(item,{cwd:result.projects[0].root,signal:abort.signal})).content.includes('EXAMPLE_BODY'));}finally{abort.abort();await fs.dispose();await ctx.fiber.dispose();}
  assert.equal(await readFile(join(localState.sources[0].root,'same','scripts','EXAMPLE.mjs'),'utf8'),'throw new Error("EXAMPLE_MUST_NOT_RUN");');assert.equal((await local.list())[0].state,'ready');assert.ok(github.inspect(f.first.sourceId,f.first.digest).release.files.length>0);
  assert.deepEqual(market.backupState(),sourceMarket);assert.deepEqual(feed.backupState(),sourceFeed);assert.equal(result.activated,false);
