async function owner(f,{home=f.appHome,profileName}={}){const previous=process.env.DSH_HOME,ctx=new Context();let reads=0;process.env.DSH_HOME=home;
  try{ctx.provide('credentials',{describe:async()=>({configured:false,writable:true}),resolve(){reads++;assert.fail('EXAMPLE_NO_KEY');}});if(profileName){const dir=resolveProfileDir(profileName,home);ctx.provide('profileContext',{name:profileName,home,dir,patchPath:join(dir,'cordis.patch.yml'),installAnchor:createRequire(import.meta.url).resolve('@deepseek-ai/dsh/package.json'),cwd:home,startedBundles:[],overlays:[]});}await ctx.plugin(LocalFs,{cwd:home});await ctx.plugin(SkillRegistry);await ctx.plugin(Prompt);await ctx.plugin(Tools);await ctx.plugin(Registry);await ctx.plugin(Access);await ctx.plugin(Zhen);ctx.typert.register(TYPERT);await ctx.plugin(Gateway,{});}finally{if(previous===undefined)delete process.env.DSH_HOME;else process.env.DSH_HOME=previous;}
  f.dispose(()=>ctx.fiber.dispose());f.dispose(()=>assert.equal(reads,0));
  const call=async(method,args={})=>{const value=await ctx.typertGateway.invoke({namespace:'zhen',method,args,peer:{id:'EXAMPLE_RESTORED_SKILLS_OWNER',ctx,principal:{kind:'owner'},signal:signal(),interactions:'none',dispose:async()=>{}}});return TYPERT_REMOTE.methods['zhen/'+method].result.create().parse(value===undefined?undefined:JSON.parse(JSON.stringify(value)));};return{ctx,call};
}
